// Auto-derive the kanata LoopGate from the active hybrid state:
//   start_pc = resume PC (from hybrid_input_state_->pc)
//   end_pc   = explicit_exit_pc when set (pc-mode -- the --hybrid-exit-pc
//              CLI value), otherwise the unique HYBRID_HANDOFF_EXIT PC
//              scanned by the CsrTrigger (csr-mode).
// Must be called AFTER apply_resume_from_qemu and enable_hybrid_handoff,
// so the resume PC and the CsrTrigger are populated.
void enable_kanata_roi(const std::string& filename,
                       const std::string& objdump_file,
                       std::optional<uint64_t> explicit_exit_pc)
{
  if (!hybrid_input_state_)
    throw std::runtime_error(
      "--kanata-roi requires --resume-from-qemu (no resume PC available)");
  if (!hybrid_handoff_)
    throw std::runtime_error(
      "--kanata-roi requires CSR or PC trigger mode");
  const auto gate = hybrid::derive_roi_kanata_gate(
    hybrid_handoff_->trigger(), hybrid_input_state_->pc, explicit_exit_pc);
  spdlog::info(
    "kanata-roi: window start=0x{:x} end=0x{:x} (skip=0 record=1)",
    gate.start_pc, gate.end_pc);
  trace_.enable_kanata(cpu, filename, objdump_file, gate);
}

